se","pattern":"core","swapGroup":"core","equipment":"bodyweight","level":"some","type":"strength","cueLine":"Hang from a bar, lift the knees to hip height, lower without swinging."},{"id":"cable-crunch","name":"Cable Crunch","pattern":"core","swapGroup":"core","equipment":"cable","level":"brandNew","type":"strength","cueLine":"Kneel facing the cable, rope behind your head, crunch the elbows toward the thighs."},{"id":"reverse-crunch","name":"Reverse Crunch","pattern":"core","swapGroup":"core","equipment":"bodyweight","level":"brandNew","type":"strength","cueLine":"On your back, knees bent, curl the hips off the floor toward your chest."},{"id":"bicycle-crunch","name":"Bicycle Crunch","pattern":"core","swapGroup":"core","equipment":"bodyweight","level":"brandNew","type":"strength","cueLine":"On your back, hands by the ears, bring the opposite elbow and knee together, slow and controlled."},{"id":"dumbbell-russian-twist","name":"Dumbbell Russian Twist","pattern":"core","swapGroup":"core","equipment":"dumbbell","level":"brandNew","type":"strength","cueLine":"Sit back to 45°, hold one dumbbell, rotate the ribs side to side."},{"id":"couch-stretch","name":"Wall Hip Flexor Stretch","pattern":"mobility","swapGroup":"hipFlexorStretch","equipment":"bodyweight","level":"brandNew","type":"mobility","holdSeconds":90,"perSide":true,"cueLine":"Kneel with the back shin up the wall, front foot forward, squeeze the glute and stay tall."},{"id":"thoracic-opener","name":"Thoracic Opener","pattern":"mobility","swapGroup":"thoracic","equipment":"bodyweight","level":"brandNew","type":"mobility","holdSeconds":90,"perSide":false,"cueLine":"Lie with a foam roller across the upper back, arms overhead, breathe into it."},{"id":"doorway-pec-stretch","name":"Rack Pec Stretch","pattern":"mobility","swapGroup":"chestOpener","equipment":"bodyweight","level":"brandNew","type":"mobility","holdSeconds":60,"perSide":true,"cueLine":"Forearm on a rack upright at shoulder height, step through until the chest opens."},{"id":"childs-pose","name":"Child's Pose","pattern":"mobility","swapGroup":"latStretch","equipment":"bodyweight","level":"brandNew","type":"mobility","holdSeconds":90,"perSide":false,"cueLine":"Knees wide, sit back onto your heels, walk the hands forward and breathe."},{"id":"pigeon-stretch","name":"Pigeon Stretch","pattern":"mobility","swapGroup":"hipOpener","equipment":"bodyweight","level":"brandNew","type":"mobility","holdSeconds":60,"perSide":true,"cueLine":"Front shin across the mat, back leg long, fold forward as far as is comfortable."},{"id":"lying-hamstring-stretch","name":"Lying Hamstring Stretch","pattern":"mobility","swapGroup":"hamstringStretch","equipment":"bodyweight","level":"brandNew","type":"mobility","holdSeconds":45,"perSide":true,"cueLine":"On your back, one leg up with a band or strap, keep the knee mostly straight."},{"id":"kneeling-hip-flexor-stretch","name":"Kneeling Hip Flexor Stretch","pattern":"mobility","swapGroup":"hipFlexorStretch","equipment":"bodyweight","level":"brandNew","type":"mobility","holdSeconds":60,"perSide":true,"cueLine":"Half-kneel, tuck the pelvis, shift forward until the front of the hip stretches."},{"id":"ninety-ninety-hip-stretch","name":"90/90 Hip Stretch","pattern":"mobility","swapGroup":"hipOpener","equipment":"bodyweight","level":"brandNew","type":"mobility","holdSeconds":60,"perSide":true,"cueLine":"Both knees at 90°, sit tall and lean over the front shin."},{"id":"cat-cow","name":"Cat-Cow","pattern":"mobility","swapGroup":"thoracic","equipment":"bodyweight","level":"brandNew","type":"mobility","holdSeconds":90,"perSide":false,"cueLine":"On all fours, arch and round the spine slowly with the breath."},{"id":"wall-lat-stretch","name":"Wall Lat Stretch","pattern":"mobility","swapGroup":"latStretch","equipment":"bodyweight","level":"brandNew","type":"mobility","holdSeconds":90,"perSide":false,"cueLine":"Hands on a wall at hip height, walk back and sink the chest toward the floor."},{"id":"wall-calf-st