d the weight.","scope":"solo","trigger":"prCount","threshold":1,"spec":"Flow 3 (PR celebrations); Flow 9 layer 3"},{"id":"saved-by-the-shield","title":"Saved by the shield","line":"A shield took the hit. Your streak lives.","scope":"solo","trigger":"shieldsConsumed","threshold":1,"spec":"Flow 7; V15"},{"id":"back-in-it","title":"Back in it","line":"The first post after a quiet stretch is the loudest one.","scope":"solo","trigger":"comebacks","threshold":1,"spec":"Flow 6 (comeback); V29"},{"id":"fifty-workouts","title":"Fifty workouts","line":"Fifty sessions logged. Sets on sets.","scope":"solo","trigger":"workoutsCompleted","threshold":50,"spec":"Flow 9 layer 1 (totals)"},{"id":"found-your-crew","title":"Found your crew","line":"You're in a crew. Nobody trains alone now.","scope":"crew","trigger":"crewJoined","threshold":1,"spec":"Flow 6; E2"},{"id":"hype","title":"Hype","line":"First reaction sent. Keep them coming.","scope":"crew","trigger":"reactionsGiven","threshold":1,"spec":"Flow 6 (reactions); V27"},{"id":"all-in","title":"All in","line":"Everyone in the crew posted today.","scope":"crew","trigger":"crewFullPulseDays","threshold":1,"spec":"Flow 6 (Crew Pulse); V37"},{"id":"perfect-crew-week","title":"Perfect crew week","line":"Seven days, every member, every day.","scope":"crew","trigger":"crewFullPulseWeeks","threshold":1,"spec":"Flow 6 (weekly crew ring); V38"}]}
